import{_ as l,o as a,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Performance Meeting 2021-07-22","description":"","frontmatter":{"title":"Ceph Performance Meeting 2021-07-22","date":"2021-07-22T00:00:00.000Z","updated":"2021-08-24T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","PR审查","RBD"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Performance_Meeting_2021-07-22.md","filePath":"posts/2021/Ceph_Performance_Meeting_2021-07-22.md","lastUpdated":1780460162000}'),r={name:"posts/2021/Ceph_Performance_Meeting_2021-07-22.md"};function o(s,e,n,h,u,d){return a(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h3><p>本次会议主要讨论了Ceph项目的多个Pull Requests (PRs)，包括新提交、更新和关闭的PRs，以及Ceph的性能改进、内存分配优化和对未来存储系统发展方向的讨论。</p><h3 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h3><ol><li><p><strong>新PR和更新PRs</strong></p><ul><li>一个新的PR改变了vlog的工作方式，Kifu已批准并要求Sam进行审查。</li><li>Radic提交了一个PR，允许Crimson使用外来的存储（alien store），以测试mem store和file store。</li><li>新的PR用于RGW跟踪，Matt已进行审查。</li><li>针对c字符串转换的buffer list优化。</li><li>一个PR改进了finisher线程的CPU占用，正在审查中。</li></ul></li><li><p><strong>关闭的PRs</strong></p><ul><li>Ori从IBM提交的PRs中，一些已被合并，一些因问题未解决而关闭。</li><li>Adam关于改变Blue Store缓存行为的旧PR被stale bot关闭。</li></ul></li><li><p><strong>性能和优化</strong></p><ul><li>讨论了在Crimson中实现multi-reactor的可能性，Greg Farnham将负责此项工作。</li><li>讨论了Randy和Radic在mem store和buffer list优化方面的工作。</li></ul></li><li><p><strong>RBD和客户端性能</strong></p><ul><li>讨论了RBD在kernel和user land客户端的性能问题，特别是与pnfs相关的讨论。</li><li>探讨了改进用户空间客户端性能的可能性，包括改进FUSE代码或探索其他技术如Zuf。</li></ul></li></ol><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li>继续推进multi-reactor的实现，以提高Ceph的性能。</li><li>继续审查和优化现有的PRs，特别是那些涉及性能和存储优化的PRs。</li><li>继续讨论和探索RBD客户端性能的改进方案。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>Greg Farnham将开始着手multi-reactor的实现工作。</li><li>继续审查和优化现有的PRs，确保它们符合项目的需求和标准。</li><li>继续讨论RBD客户端性能的改进方案，并寻求社区的反馈和建议。</li></ul><h3 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h3><ul><li>会议还讨论了一些正在进行中的测试和未来的工作计划，包括对bidding code和blue fs的改进。</li></ul><h3 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h3><p>会议在讨论了所有议题后结束，与会者被鼓励继续工作并享受即将到来的周末。</p>',12)])])}const m=l(r,[["render",o]]);export{c as __pageData,m as default};
